mapper.select:
SELECT l.log_id, l.project_id, l.seal_id, l.user_id, l.file_hash,
       l.client_ip, l.ip_location, l.remark, l.output_file_id,
       l.cert_id, l.action_type, l.result_code, l.trace_id,
       l.sign_time, l.create_time, l.tenant_id, l.create_user, l.dept_id,
       p.project_name, s.seal_name,
       u.username AS user_name, u.nickname AS nick_name
FROM sign_log l
LEFT JOIN sign_project p ON l.project_id = p.project_id
LEFT JOIN sign_seal s ON l.seal_id = s.seal_id
LEFT JOIN sys_user u ON l.user_id = u.id

    AND l.log_id = #{logId}
    AND l.project_id = #{projectId}
    AND l.seal_id = #{sealId}
    AND l.user_id = #{userId}
    AND l.action_type = #{actionType}
    AND u.username LIKE CONCAT('%', #{userName}, '%')
    
        AND l.sign_time >= #{params.beginTime}
    
    
        AND l.sign_time <= #{params.endTime}
    
    

ORDER BY l.sign_time DESC

mapper.insert:
