    remark, output_file_id, cert_id, action_type, result_code,
    trace_id, sign_time, create_time, tenant_id, create_user, dept_id
) VALUES (
    #{projectId}, #{sealId}, #{userId}, #{fileHash}, #{clientIp}, #{ipLocation},
    #{remark}, #{outputFileId}, #{certId}, #{actionType}, #{resultCode},
    #{traceId}, #{signTime}, #{createTime}, #{tenantId}, #{createUser}, #{deptId}
)
